<template><CoopTaskSheet :show="show" title="ERP 连接与库存采集" :busy="busy" full @close="close"><view class="coop-form-section"><view class="coop-section-title">当前接入<text>{{ connection.provider_name || schema?.name || '尚未接入' }}</text></view><view class="coop-muted">{{ connection.last_sync_message || '先正常登录核对来源门店，再明确启用。只读库存，不修改 ERP。' }}</view><view class="coop-detail-shop"><text>最近同步</text><text>{{ coopDate(connection.last_sync_at) }}</text></view><view class="coop-detail-shop"><text>同步状态</text><text>{{ run.status || connection.last_sync_status || '未开始' }}</text></view><view v-if="run.id" class="coop-muted">已读取 {{ run.page_count || 0 }} 页 · {{ run.record_count || 0 }} 条来源资料</view><view class="coop-small-actions"><u-button size="small" text="刷新状态" :disabled="busy" @click="refresh" /><u-button v-if="connection.enabled" size="small" type="primary" :text="run.status === 'running' || run.status === 'pending' ? '继续本次同步' : '同步库存'" :loading="busy" @click="sync" /></view></view><view class="coop-form-section"><view class="coop-section-title">授权登录<text @tap="editing = !editing">{{ editing ? '收起' : '重新授权' }}</text></view><template v-if="editing || !connection.connected"><view class="coop-form-column"><text>ERP 来源</text><picker :range="providers" range-key="name" :value="providerIndex" :disabled="busy" @change="changeProvider(providers[Number($event.detail.value)]?.key || '')"><view class="coop-picker-field">{{ schema?.name || '选择 ERP' }} ›</view></picker></view><view v-for="field in credentialFields" :key="field.key" class="coop-form-column"><text>{{ field.label }}</text><u-input v-model="credentials[field.key]" :password="!!field.secret" :disabled="busy" :maxlength="field.max_length || 512" :placeholder="`填写${field.label}`" /></view><template v-if="interactive"><view v-for="field in schema?.interactive_auth?.fields || []" :key="field.key" class="coop-form-column"><text>{{ field.label }}</text><u-input v-model="authorization[field.key]" :password="!!field.secret" :disabled="busy" :maxlength="field.max_length || 4096" :placeholder="`填写${field.label}`" /></view><view class="coop-captcha-row"><image v-if="captchaImage" :src="captchaImage" mode="aspectFit" @tap="challenge" /><u-button size="small" :disabled="busy" :text="captchaImage ? '刷新验证码' : '获取验证码'" @click="challenge" /></view><view class="coop-form-column"><text>图片验证码</text><u-input v-model="authorization.code" maxlength="4" placeholder="填写图片中的验证码" :disabled="busy" /></view><picker v-if="companies.length" :range="companies" range-key="name" :value="companyIndex" :disabled="busy" @change="companyId = String(companies[Number($event.detail.value)]?.id || '')"><view class="coop-picker-field">{{ companies[companyIndex]?.name || '选择所属公司' }} ›</view></picker></template><view v-if="scopeFields.length" class="coop-fold-title" @tap="scopeOpen = !scopeOpen">来源范围（通常自动识别）<u-icon :name="scopeOpen ? 'arrow-up' : 'arrow-down'" size="12" color="#89939f" /></view><template v-if="scopeOpen"><view v-for="field in scopeFields" :key="field.key" class="coop-form-column"><text>{{ field.label }}</text><u-input v-model="scope[field.key]" :disabled="busy" :placeholder="field.required ? '必填' : '可留空自动核对'" /></view></template><u-button type="primary" shape="circle" text="只读验证并预览" :loading="busy" :disabled="!schema || busy" @click="probe" /></template></view><view v-if="preview" class="coop-form-section"><view class="coop-section-title">核对本次来源</view><view class="coop-muted">{{ preview.note }}</view><view class="coop-detail-shop"><text>来源门店</text><text>{{ preview.identity?.name || preview.identity?.store_id || '尚未核对' }}</text></view><view class="coop-detail-shop"><text>首屏资料</text><text>{{ preview.first_page_count ?? '—' }} 条，不代表完整库存</text></view><picker v-if="preview.requires_store_selection" :range="preview.stores || []" range-key="name" :value="storeIndex" :disabled="busy" @change="scope.store_id = String(preview.stores[Number($event.detail.value)]?.store_id || '')"><view class="coop-picker-field">{{ scope.store_id || '选择一个来源门店后重新验证' }} ›</view></picker><view class="coop-consent" @tap="!busy && (confirmed = !confirmed)"><u-icon :name="confirmed ? 'checkmark-circle-fill' : 'circle'" size="19" :color="confirmed ? 'var(--primary-color, #d93833)' : '#b9c3d0'" /><text>已核对账号及门店，确认启用当前接入。更换账号会影响后续库存匹配。</text></view><u-button shape="circle" type="primary" text="确认启用，并准备同步" :disabled="busy || !confirmed || preview.can_activate === false || preview.requires_store_selection" :loading="busy" @click="activate" /></view><view v-if="error" class="coop-inline-error coop-form-error">{{ error }}</view><view class="coop-task-rule">验证码或账号校验失败时不会变更原接入。若来源需扫码或子账号，请使用已获商户授权的账号；不绕过平台验证。</view><template #footer><u-button shape="circle" text="完成，返回" :disabled="busy" @click="close" /></template></CoopTaskSheet></template>
<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { cooperationConnection, cooperationChallenge, cooperationProbe, cooperationActivate, cooperationSync, cooperationSyncInfo, cooperationSyncAdvance, coopDate, coopError, type CoopRow } from '../../api/cooperation'
import CoopTaskSheet from './CoopTaskSheet.vue'
const props = defineProps<{ show: boolean; profile: CoopRow; providers: CoopRow[] }>()
const emit = defineEmits<{ (event: 'close' | 'changed'): void }>()
const connection = ref<CoopRow>({}), run = ref<CoopRow>({}), provider = ref(''), credentials = reactive<CoopRow>({}), authorization = reactive<CoopRow>({}), scope = reactive<CoopRow>({}), busy = ref(false), error = ref(''), editing = ref(false), scopeOpen = ref(false), captchaImage = ref(''), challengeToken = ref(''), challengeExpires = ref(0), companies = ref<CoopRow[]>([]), companyId = ref(''), preview = ref<CoopRow | null>(null), probeToken = ref(''), confirmed = ref(false)
const schema = computed(() => props.providers.find(item => item.key === provider.value)), providerIndex = computed(() => Math.max(0, props.providers.findIndex(item => item.key === provider.value))), interactive = computed(() => schema.value?.interactive_auth?.type === 'image_captcha')
const defaultMode = computed(() => schema.value?.auth_modes?.find((item: CoopRow) => item.key === 'password') || schema.value?.auth_modes?.[0]), credentialFields = computed<CoopRow[]>(() => interactive.value ? (schema.value?.fields || []).filter((field: CoopRow) => (schema.value?.interactive_auth?.credential_fields || []).includes(field.key)) : defaultMode.value?.fields || schema.value?.fields || []), scopeFields = computed<CoopRow[]>(() => defaultMode.value?.scope_fields || schema.value?.scope_fields || [])
const companyIndex = computed(() => Math.max(0, companies.value.findIndex(item => String(item.id) === companyId.value))), storeIndex = computed(() => Math.max(0, (preview.value?.stores || []).findIndex((item: CoopRow) => String(item.store_id) === String(scope.store_id))))
let sequence = 0
function clearSecret() { Object.keys(credentials).forEach(key => delete credentials[key]); Object.keys(authorization).forEach(key => delete authorization[key]); challengeToken.value = ''; captchaImage.value = ''; challengeExpires.value = 0; companies.value = []; companyId.value = '' }
function changeProvider(value: string) { if (busy.value) return; provider.value = value; clearSecret(); Object.keys(scope).forEach(key => delete scope[key]); preview.value = null; probeToken.value = ''; confirmed.value = false; error.value = '' }
async function guard(work: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; const token = ++sequence; try { await work() } catch (cause) { if (token === sequence && props.show) error.value = coopError(cause, '处理未完成，原接入保持不变') } finally { if (token === sequence) busy.value = false } }
async function refresh() { await guard(async () => { const result: any = await cooperationConnection(); if (!props.show) return; connection.value = result.data || {}; if (Number(connection.value.active_run_id)) { const info: any = await cooperationSyncInfo(Number(connection.value.active_run_id)); if (props.show) run.value = info.data || {} } }) }
function payload() { return { provider: provider.value, credentials: { ...credentials, ...(defaultMode.value ? { auth_mode: defaultMode.value.key } : {}) }, scope: { ...scope } } }
async function challenge() { await guard(async () => { const result: any = await cooperationChallenge(payload()); if (!props.show) return; challengeToken.value = result.data?.challenge_token || ''; captchaImage.value = result.data?.captcha_image || ''; challengeExpires.value = Number(result.data?.expires_at || 0); authorization.code = ''; companies.value = [] }) }
async function probe() { await guard(async () => { for (const field of credentialFields.value) if (field.required && !String(credentials[field.key] || '').trim()) throw new Error(`请填写${field.label}`); const input: CoopRow = payload(); if (interactive.value) { if (!challengeToken.value || challengeExpires.value * 1000 <= Date.now()) throw new Error('请重新获取有效验证码'); input.authorization = companies.value.length ? { challenge_token: challengeToken.value, company_id: companyId.value } : { ...authorization, challenge_token: challengeToken.value } }; const result: any = await cooperationProbe(input); if (!props.show) return; const data = result.data || {}; if (data.status === 'choose_company' || data.authorization_required) { companies.value = data.companies || data.public?.companies || []; challengeToken.value = data.challenge_token || data.public?.challenge_token || ''; companyId.value = String(companies.value[0]?.id || ''); return }; preview.value = data.preview || null; probeToken.value = data.probe_token || ''; confirmed.value = false; authorization.password = ''; authorization.code = '' }) }
async function activate() { if (!confirmed.value || !probeToken.value) return; await guard(async () => { const result: any = await cooperationActivate({ probe_token: probeToken.value, confirm_switch: true, store_id: scope.store_id || '' }); if (!props.show) return; connection.value = result.data || {}; preview.value = null; probeToken.value = ''; clearSecret(); editing.value = false; emit('changed'); uni.showToast({ title: '接入已启用，请继续同步库存', icon: 'none' }) }) }
async function sync() { await guard(async () => { const result: any = run.value.id && ['running', 'pending'].includes(run.value.status) ? await cooperationSyncAdvance(Number(run.value.id)) : await cooperationSync(); if (!props.show) return; const data = result.data || {}; run.value = data.run || data; if (!run.value.id && Number(data.run_id)) { const info: any = await cooperationSyncInfo(Number(data.run_id)); run.value = info.data || {} }; emit('changed') }) }
function close() { if (busy.value) return; sequence++; clearSecret(); preview.value = null; emit('close') }
watch(() => props.show, show => { if (show) { provider.value = props.profile.connection?.provider || props.profile.provider_requested || props.providers[0]?.key || ''; connection.value = props.profile.connection || {}; preview.value = null; run.value = {}; editing.value = !connection.value.connected; void refresh() } else { sequence++; busy.value = false; clearSecret() } })
watch(() => JSON.stringify(credentials), () => { preview.value = null; probeToken.value = ''; confirmed.value = false })
watch(() => JSON.stringify(scope), () => { preview.value = null; probeToken.value = ''; confirmed.value = false })
onBeforeUnmount(() => { sequence++; clearSecret() })
</script>
